package com.wanyuecity.energy.verification.service;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.wanyuecity.energy.core.BizException; import com.wanyuecity.energy.verification.entity.*; import com.wanyuecity.energy.verification.mapper.*; import com.wanyuecity.energy.verification.service.dto.AttachmentView; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile;
import java.io.*; import java.nio.file.*; import java.security.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class AttachmentService {
 private final AttachmentMapper attachmentMapper; private final FieldVerificationTaskMapper taskMapper; private final FieldVerificationDeviceMapper deviceMapper;
 @Value("${energy.upload.base-dir}") private String baseDir;
 @Transactional public AttachmentView upload(String token,Long deviceId,String photoType,MultipartFile file){FieldVerificationTask task=requireTask(token);FieldVerificationDevice device=deviceMapper.selectById(deviceId);if(device==null||!task.getId().equals(device.getVerificationTaskId()))throw BizException.notFound("verification device not found");
  String type=photoType==null?"":photoType.trim().toUpperCase();if(!Set.of("LOCATION","METER_FACE","SERIAL_NUMBER","OTHER").contains(type))throw BizException.badRequest("invalid photoType");if(file==null||file.isEmpty())throw BizException.badRequest("image file is required");if(file.getSize()>10*1024*1024)throw BizException.badRequest("image exceeds 10MB");String mime=Optional.ofNullable(file.getContentType()).orElse("");if(!Set.of("image/jpeg","image/png").contains(mime))throw BizException.badRequest("only JPEG and PNG images are allowed");
  try{byte[] bytes=file.getBytes();String sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));String ext="image/png".equals(mime)?".png":".jpg";Path root=Path.of(baseDir).toAbsolutePath().normalize();Path dir=root.resolve(LocalDate.now().toString()).resolve(String.valueOf(task.getId())).normalize();if(!dir.startsWith(root))throw BizException.badRequest("invalid storage path");Files.createDirectories(dir);String stored=UUID.randomUUID()+ext;Path target=dir.resolve(stored);Files.write(target,bytes,StandardOpenOption.CREATE_NEW);
   Attachment a=new Attachment();a.setBusinessType("VERIFICATION_DEVICE");a.setBusinessId(deviceId);a.setFileType("IMAGE");a.setFileName(safeName(file.getOriginalFilename(),stored));a.setStorageProvider("LOCAL");a.setStoragePath(root.relativize(target).toString());a.setFileSize(file.getSize());a.setMimeType(mime);a.setSha256(sha);a.setPhotoType(type);a.setUploadedAt(LocalDateTime.now());attachmentMapper.insert(a);return view(a);
  }catch(IOException|NoSuchAlgorithmException e){throw new BizException("failed to store image: "+e.getClass().getSimpleName());}}
 public List<AttachmentView> list(String token,Long deviceId){FieldVerificationTask task=requireTask(token);FieldVerificationDevice d=deviceMapper.selectById(deviceId);if(d==null||!task.getId().equals(d.getVerificationTaskId()))throw BizException.notFound("verification device not found");return attachmentMapper.selectList(new QueryWrapper<Attachment>().eq("business_type","VERIFICATION_DEVICE").eq("business_id",deviceId).orderByAsc("uploaded_at")).stream().map(this::view).toList();}
 public ResourceContent read(String token,Long id){FieldVerificationTask task=requireTask(token);Attachment a=attachmentMapper.selectById(id);if(a==null||!"VERIFICATION_DEVICE".equals(a.getBusinessType()))throw BizException.notFound("attachment not found");FieldVerificationDevice d=deviceMapper.selectById(a.getBusinessId());if(d==null||!task.getId().equals(d.getVerificationTaskId()))throw BizException.notFound("attachment not found");Path root=Path.of(baseDir).toAbsolutePath().normalize();Path file=root.resolve(a.getStoragePath()).normalize();if(!file.startsWith(root)||!Files.isRegularFile(file))throw BizException.notFound("attachment file not found");return new ResourceContent(new FileSystemResource(file),a.getMimeType(),a.getFileName());}
 private FieldVerificationTask requireTask(String token){if(token==null||token.length()<32)throw BizException.notFound("verification task not found");FieldVerificationTask t=taskMapper.selectOne(new QueryWrapper<FieldVerificationTask>().eq("access_token",token).last("LIMIT 1"));if(t==null)throw BizException.notFound("verification task not found");return t;}
 private AttachmentView view(Attachment a){AttachmentView v=new AttachmentView();v.setId(a.getId());v.setDeviceId(a.getBusinessId());v.setFileName(a.getFileName());v.setFileSize(a.getFileSize());v.setMimeType(a.getMimeType());v.setSha256(a.getSha256());v.setPhotoType(a.getPhotoType());v.setUploadedAt(a.getUploadedAt());return v;}
 private String safeName(String name,String fallback){if(name==null||name.isBlank())return fallback;return Path.of(name).getFileName().toString();}
 public record ResourceContent(Resource resource,String mimeType,String fileName){}
}

